	return b.parents
}

// bomRef returns BOMRef for CycloneDX
// When multiple lock files have the same dependency with the same name and version, PURL in the BOM can conflict.
// In that case, PURL cannot be used as a unique identifier, and UUIDv4 be used for BOMRef.
func (b *BOM) bomRef(c *Component) string {
	if c.PkgIdentifier.BOMRef != "" {
		return c.PkgIdentifier.BOMRef
	}
	// Return the UUID of the component if the PURL is not present.
	if c.PkgIdentifier.PURL == nil {
		return c.id.String()
	}
	p := c.PkgIdentifier.PURL.String()

	// Return the UUID of the component if the PURL is not unique in the BOM.
	if len(b.purls[p]) > 1 {
		return c.id.String()
	}
	return p
}

// Clone creates a deep copy of the BOM, including all components, relationships, and vulnerabilities.
// This ensures that modifications to the cloned BOM do not affect the original BOM.
func (b *BOM) Clone() *BOM {
	return &BOM{
		SerialNumber: b.SerialNumber,
		Version:      b.Version,
		rootID:       b.rootID,

		// Deep copy components
		components: lo.MapValues(b.components, func(c *Component, _ uuid.UUID) *Component {
			return c.Clone()
		}),

		// Deep copy cryptographic components
		cryptoComponents: lo.Map(b.cryptoComponents, func(c *CryptoComponent, _ int) *CryptoComponent {
			return c.Clone()
		}),

		// Deep copy relationships
		relationships: lo.MapValues(b.relationships, func(rels []Relationship, _ uuid.UUID) []Relationship {
			return slices.Clone(rels)
		}),

		// Deep copy vulnerabilities
		vulnerabilities: lo.MapValues(b.vulnerabilities, func(vulns []Vulnerability, _ uuid.UUID) []Vulnerability {
			return slices.Clone(vulns)
		}),

		// Deep copy external references
		externalReferences: slices.Clone(b.externalReferences),

		// Deep copy purls
		purls: lo.MapValues(b.purls, func(ids []uuid.UUID, _ string) []uuid.UUID {
			return slices.Clone(ids)
		}),

		// Deep copy parents
		parents: lo.MapValues(b.parents, func(parentIds []uuid.UUID, _ uuid.UUID) []uuid.UUID {
			return slices.Clone(parentIds)
		}),

		opts: b.opts,
	}
}

