package main

import (
	"log"
	"os"

	cdx "github.com/CycloneDX/cyclonedx-go"
)

func main() {
	in, err := os.Open(os.Args[1])
	if err != nil {
		log.Fatal(err)
	}
	defer in.Close()

	var bom cdx.BOM
	if err = cdx.NewBOMDecoder(in, cdx.BOMFileFormatJSON).Decode(&bom); err != nil {
		log.Fatal(err)
	}

	out, err := os.Create(os.Args[1])
	if err != nil {
		log.Fatal(err)
	}
	defer out.Close()

	encoder := cdx.NewBOMEncoder(out, cdx.BOMFileFormatJSON)
	encoder.SetPretty(true)
	encoder.SetEscapeHTML(false)
	if err = encoder.EncodeVersion(&bom, cdx.SpecVersion1_6); err != nil {
		log.Fatal(err)
	}
}

