package licensing

import (
	"strings"

	"github.com/samber/lo"

	"github.com/aquasecurity/trivy/pkg/fanal/types"
	"github.com/aquasecurity/trivy/pkg/licensing/expression"
)

// Policy selects components by license. A component is excluded when any of its licenses
// matches one of the configured categories or license expressions.
type Policy struct {
	categories map[types.LicenseCategory]struct{}
	licenses   map[string]struct{}
	scanner    Scanner
}

// NewPolicy builds a license policy. Entries can be license categories such as
// "forbidden" or license expressions such as "GPL-3.0-only" and "MIT OR Apache-2.0".
// The optional prefix "category:" or "license:" disambiguates an entry.
func NewPolicy(entries []string, categories map[types.LicenseCategory][]string) Policy {
	if len(categories) == 0 {
		categories = map[types.LicenseCategory][]string{
			types.CategoryForbidden:    expression.ForbiddenLicenses,
			types.CategoryRestricted:   expression.RestrictedLicenses,
			types.CategoryReciprocal:   expression.ReciprocalLicenses,
			types.CategoryNotice:       expression.NoticeLicenses,
			types.CategoryPermissive:   expression.PermissiveLicenses,
			types.CategoryUnencumbered: expression.UnencumberedLicenses,
		}
	}
	policy := Policy{
		categories: make(map[types.LicenseCategory]struct{}),
		licenses:   make(map[string]struct{}),
		scanner:    NewScanner(categories),
	}

	for _, entry := range entries {
		entry = strings.TrimSpace(entry)
		if entry == "" {
			continue
		}

		kind, value, found := strings.Cut(entry, ":")
		if !found {
			value = entry
		}

		if (found && strings.EqualFold(kind, "category")) || (!found && isLicenseCategory(value)) {
			policy.categories[licenseCategory(value)] = struct{}{}
			continue
		}
		if found && !strings.EqualFold(kind, "license") {
			// Unknown prefixes are treated as part of the license name.
			value = entry
		}

		policy.addLicense(value)
	}

	return policy
}

// Empty reports whether the policy contains no criteria.
func (p Policy) Empty() bool {
	return len(p.categories) == 0 && len(p.licenses) == 0
}

// Excludes reports whether any of the licenses violates the policy.
func (p Policy) Excludes(licenses []string) bool {
	licenses = lo.Compact(lo.Map(licenses, func(license string, _ int) string {
		return strings.TrimSpace(license)
	}))

	if len(licenses) == 0 {
		_, excluded := p.categories[types.CategoryUnknown]
		return excluded
	}

	for _, license := range licenses {
		if p.matchesLicense(license) {
			return true
		}
		category, _ := p.scanner.Scan(license)
		if _, excluded := p.categories[category]; excluded {
			return true
		}
	}
	return false
}

func (p *Policy) addLicense(license string) {
	if names := normalizeLicenseNames(license); len(names) > 0 {
		for _, name := range names {
			p.licenses[name] = struct{}{}
		}
		return
	}
	p.licenses[strings.ToLower(strings.TrimSpace(license))] = struct{}{}
}

func (p Policy) matchesLicense(license string) bool {
	names := normalizeLicenseNames(license)
	if len(names) == 0 {
		names = []string{strings.ToLower(strings.TrimSpace(license))}
	}
	for _, name := range names {
		if _, excluded := p.licenses[name]; excluded {
			return true
		}
	}
	return false
}

func normalizeLicenseNames(license string) []string {
	expr, err := expression.Normalize(license, NormalizeLicenseExpression, expression.NormalizeForSPDX)
	if err != nil {
		return nil
	}

	var names []string
	var walk func(expression.Expression)
	walk = func(expr expression.Expression) {
		switch e := expr.(type) {
		case expression.SimpleExpr:
			names = append(names, strings.ToLower(e.String()))
		case expression.CompoundExpr:
			walk(e.Left())
			walk(e.Right())
		}
	}
	walk(expr)
	return lo.Uniq(names)
}

func isLicenseCategory(value string) bool {
	switch strings.ToLower(value) {
	case string(types.CategoryForbidden),
		string(types.CategoryRestricted),
		string(types.CategoryReciprocal),
		string(types.CategoryNotice),
		string(types.CategoryPermissive),
		string(types.CategoryUnencumbered),
		string(types.CategoryUnknown):
		return true
	default:
		return false
	}
}

func licenseCategory(value string) types.LicenseCategory {
	return types.LicenseCategory(strings.ToLower(strings.TrimSpace(value)))
}

	return &cdxComponents, nil
}

func (m *Marshaler) marshalDependencies() *[]cdx.Dependency {
	dependencies := make(map[string]map[string]struct{})

	// Every component must be present in the dependency graph, even when it has no
	// dependencies of its own. Otherwise validators cannot tell "no dependencies" from
	// "dependency information is missing".
	for _, component := range m.bom.Components() {
		if ref, ok := m.componentIDs[component.ID()]; ok {
			m.addDependency(dependencies, ref)
		}
	}

	for key, rels := range m.bom.Relationships() {
		ref, ok := m.componentIDs[key]
		if !ok {
			continue
		}

		m.addDependency(dependencies, ref)
		for _, rel := range rels {
			if dependency, ok := m.componentIDs[rel.Dependency]; ok {
				dependencies[ref][dependency] = struct{}{}
			}
		}
	}

	// A cryptographic asset depends on nothing, and CycloneDX tells that apart from unknown
	// dependencies only by the component being declared as an empty element of the graph.
	// https://cyclonedx.org/docs/1.7/json/#dependencies
	for _, component := range m.bom.CryptoComponents() {
		m.addDependency(dependencies, component.BOMRef())
	}

	dependencyList := lo.MapToSlice(dependencies, func(ref string, deps map[string]struct{}) cdx.Dependency {
		sorted := lo.Keys(deps)
		sort.Strings(sorted)
		return cdx.Dependency{
			Ref:          ref,
			Dependencies: &sorted,
		}
	})

	// Sort dependencies by BOM-Ref
	sort.Slice(dependencyList, func(i, j int) bool {
		return dependencyList[i].Ref < dependencyList[j].Ref
	})
	return &dependencyList
}

func (*Marshaler) addDependency(dependencies map[string]map[string]struct{}, ref string) {
	if ref == "" {
		return
	}
	if _, ok := dependencies[ref]; !ok {
		dependencies[ref] = make(map[string]struct{})
	}
}

func (m *Marshaler) marshalVulnerabilities() *[]cdx.Vulnerability {
	vulns := make(map[string]*cdx.Vulnerability)
	for id, vv := range m.bom.Vulnerabilities() {
		bomRef := m.componentIDs[id]
		for _, v := range vv {
			// If the same vulnerability affects multiple packages, those packages will be aggregated into one vulnerability.
			//   Vulnerability component (CVE-2020-26247)
			//     -> Library component (nokogiri /srv/app1/vendor/bundle/ruby/3.0.0/specifications/nokogiri-1.10.0.gemspec)
			//     -> Library component (nokogiri /srv/app2/vendor/bundle/ruby/3.0.0/specifications/nokogiri-1.10.0.gemspec)
			if vuln, ok := vulns[v.ID]; ok {
				*vuln.Affects = append(*vuln.Affects, m.affects(bomRef, v.InstalledVersion))
				if v.FixedVersion != "" {
					// new recommendation
					rec := fmt.Sprintf("Upgrade %s to version %s", v.PkgName, v.FixedVersion)
					// previous recommendations
					recs := strings.Split(vuln.Recommendation, "; ")
					if !slices.Contains(recs, rec) {
						recs = append(recs, rec)
						slices.Sort(recs)
						vuln.Recommendation = strings.Join(recs, "; ")
					}
				}
			} else {
				vulns[v.ID] = m.marshalVulnerability(bomRef, v)
			}
		}
	}

	vulnList := lo.MapToSlice(vulns, func(_ string, value *cdx.Vulnerability) cdx.Vulnerability {
		sort.Slice(*value.Affects, func(i, j int) bool {
			return (*value.Affects)[i].Ref < (*value.Affects)[j].Ref
		})
		return *value
	})
	sort.Slice(vulnList, func(i, j int) bool {
		return vulnList[i].ID < vulnList[j].ID
	})
	return &vulnList
}

package cyclonedx

import (
	"context"
	"io"

	cdx "github.com/CycloneDX/cyclonedx-go"
	"golang.org/x/xerrors"

	ftypes "github.com/aquasecurity/trivy/pkg/fanal/types"
	"github.com/aquasecurity/trivy/pkg/licensing"
	"github.com/aquasecurity/trivy/pkg/sbom/cyclonedx"
	"github.com/aquasecurity/trivy/pkg/types"
)

// Writer implements types.Writer
type Writer struct {
	output        io.Writer
	format        cdx.BOMFileFormat
	specVersion   cdx.SpecVersion
	licensePolicy licensing.Policy
	marshaler     cyclonedx.Marshaler
}

type Option func(*Writer)

// WithSpecVersion sets the CycloneDX specification version. Supported values are "1.6" and "1.7".
func WithSpecVersion(version string) Option {
	return func(w *Writer) {
		switch version {
		case "1.6":
			w.specVersion = cdx.SpecVersion1_6
		case "1.7":
			w.specVersion = cdx.SpecVersion1_7
		}
	}
}

// WithLicensePolicy excludes components matching the license policy.
func WithLicensePolicy(entries []string, categories map[ftypes.LicenseCategory][]string) Option {
	return func(w *Writer) {
		w.licensePolicy = licensing.NewPolicy(entries, categories)
	}
}

func NewWriter(output io.Writer, appVersion string, opts ...Option) Writer {
	w := Writer{
		output:      output,
		format:      cdx.BOMFileFormatJSON,
		specVersion: cdx.SpecVersion1_6,
	}
	for _, opt := range opts {
		opt(&w)
	}

	marshalerOpts := []cyclonedx.MarshalerOption{
		cyclonedx.WithSpecVersion(w.specVersion),
	}
	if !w.licensePolicy.Empty() {
		marshalerOpts = append(marshalerOpts, cyclonedx.WithLicensePolicy(w.licensePolicy))
	}
	w.marshaler = cyclonedx.NewMarshaler(appVersion, marshalerOpts...)
	return w
}

// Write writes the results in CycloneDX format
func (w Writer) Write(ctx context.Context, report types.Report) error {
	bom, err := w.marshaler.MarshalReport(ctx, report)
	if err != nil {
		return xerrors.Errorf("CycloneDX marshal error: %w", err)
	}

	encoder := cdx.NewBOMEncoder(w.output, w.format)
	encoder.SetPretty(true)
	encoder.SetEscapeHTML(false)
	if err = encoder.EncodeVersion(bom, w.specVersion); err != nil {
		return xerrors.Errorf("failed to encode bom: %w", err)
	}

	return nil
}

